    explainRepo: {
        parameters: {
            query: {
                /** @description The deep code question (e.g. 'where are transaction result codes defined'). */
                q: string;
                /** @description Optional owner/name to pin the repo (e.g. stellar/stellar-core). Omit to auto-route. */
                repo?: string;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Routed repo + DeepWiki-grounded answer */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        ok?: boolean;
                        /** @description Provenance: routing/grounding source + generation time. */
                        meta?: {
                            source?: string;
                            /** Format: date-time */
                            generatedAt?: string;
                            note?: string;
                            /** @description THIS OPERATION ONLY: present on deepwiki-grounded answers, carrying the answer-dating disclaimer (answerAsOf is null; scannedAt/scannedRef/lastCommitAt date OUR SOURCE SCAN, not the answer). Unlike the shared Meta.warnings (ignored-query-param disclosure), it says nothing about your request parameters. */
                            warnings?: string[];
                        };
                        q?: string;
                        repo?: string | null;
                        /** @description How the repo was chosen: explicit | canonical | search. null when nothing routed. */
                        routedVia?: string | null;
                        /** @description Freshness/status of the routed repo from the StellarLight INDEX — these dates cover our index's view of the repo, explicitly NOT the answer. Never attach lastCommitAt as the answer's as-of date: the answer is dated by answerAsOf alone, and a DeepWiki answer can predate lastCommitAt and contradict the code at it. Null when the repo isn't indexed or nothing routed. */
                        repoMeta?: {
                            /** Format: date-time */
                            lastCommitAt?: string | null;
                            stars?: number | null;
                            isArchived?: boolean;
                            repoScoreLabel?: string | null;
                        } | null;
                        /** @description Code-verified truth from analyzing the routed repo's ACTUAL source — qualify the answer with it: a deployable contract on a supported soroban-sdk is authoritative; tooling that merely uses Stellar is not. Null until code-scanned. */
                        codeVerified?: {
                            stellarProof?: string;
                            codeDepth?: number | null;
                            /** @description The routed repo's PRODUCT is a deployable Soroban contract. Known platform/SDK/tooling repos (stellar-core, rs-soroban-env, the SDKs/CLI/RPC…) are pinned FALSE — they vendor cdylib crates as runtime/fixtures, and this flag must never be read as 'Stellar Core itself is deployable'. */
                            isDeployableContract?: boolean;
                            sorobanSdkVersion?: string | null;
                            versionStatus?: string | null;
                            /** @description Deterministic trust score for the code facts (basis code-scan × freshness of scannedAt). Null when never scanned. */
                            codeConfidence?: {
                                score?: number;
                                /** @enum {string} */
                                label?: "high" | "medium" | "low";
                                ageDays?: number | null;
                            } | null;
                            /** Format: date-time */
                            scannedAt?: string | null;
                            /** @description Commit SHA of the default branch the code facts were computed at — cite github.com/<fullName>/tree/<scannedRef>. Null on scans before 2026-08-12. */
                            scannedRef?: string | null;
                            symbols?: string[];
                            contractInterface?: string[];
                            targetProtocol?: number | null;
                            protocolCaps?: {
                                cap?: number;
                                title?: string;
                                status?: string | null;
                                url?: string;
                            }[];
                            stellarDeps?: string[];
                            mainnetContractId?: string | null;
                            sdkCapabilities?: string[];
                        } | null;
                        /** @description DeepWiki source-grounded answer; null if DeepWiki had no answer (routed repo still returned). */
                        answer?: string | null;
                        /** @description Where the answer text came from ('deepwiki' | 'stellarlight-code-scan'); null when no answer was produced — cite it alongside the answer. It states the GROUNDING, never the age: see answerAsOf. */
                        answerSource?: string | null;
                        /**
                         * Format: date-time
                         * @description When the answer was true. NULL WHENEVER answerSource is 'deepwiki' — DeepWiki exposes no index date, so the age of such an answer is genuinely unknown and we will not invent one. Do NOT substitute codeVerified.scannedAt, codeVerified.scannedRef or repoMeta.lastCommitAt: those date OUR SOURCE SCAN, and a DeepWiki answer can be older than the scanned ref and contradict it (reported 2026-08-31: an answer said MaxSupportedProtocolVersion = 25 while the source at the scanned ref defined 28). Populated only for answerSource 'stellarlight-code-scan', where the answer IS the scan and scannedAt dates it. When null, verify any specific value against repoUrl at scannedRef.
                         */
                        answerAsOf?: string | null;
                        /** @description Always present, including when routedVia is null (then false). */
                        answered?: boolean;
                        /** @description Other authoritative repos for this concept. Always present ([] when none). */
                        alternateRepos?: string[];
                        /** @description Always present; fields are null when nothing was routed. */
                        sources?: {
                            repoUrl?: string | null;
                            deepWikiUrl?: string | null;
                            deepWikiSearchUrl?: string | null;
                        };
                        /** @description Present when routing failed entirely — a hint to use search_repos or pin ?repo=. */
                        note?: string | null;
                        /** @description Present when a repo routed but DeepWiki had no answer. */
                        note2?: string | null;
                    };
                };
            };
            /** @description Missing q */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
        };
    };
